-- ============================================================
-- Migration 001: Initial Schema
-- FitPilot AI — Phase 1
-- ============================================================
-- Run this against your Supabase project via:
--   Supabase Dashboard → SQL Editor → paste and run
-- Or via Supabase CLI:
--   supabase db push
--
-- Convention:
--   - All timestamps are TIMESTAMPTZ (timezone-aware)
--   - All PKs are UUIDs generated by gen_random_uuid()
--   - Soft deletes: not used in Phase 1 (keep it simple)
--   - All user data rows include user_id referencing auth.users

-- ── Extensions ────────────────────────────────────────────────────────────────
-- uuid-ossp is available on Supabase by default
-- We use gen_random_uuid() (pgcrypto) which is also built-in

-- ── User Profiles ─────────────────────────────────────────────────────────────
-- Extends Supabase Auth (auth.users) with app-specific profile data.
-- One row per user. Created after successful registration.

CREATE TABLE IF NOT EXISTS public.user_profiles (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id         UUID NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,

  -- Personal info
  display_name    TEXT,
  date_of_birth   DATE,
  gender          TEXT CHECK (gender IN ('male', 'female', 'other', 'prefer_not_to_say')),

  -- Body metrics (stored in metric units; app converts for display)
  height_cm       NUMERIC(5, 1),          -- e.g. 175.5
  weight_kg       NUMERIC(5, 2),          -- e.g. 72.50

  -- Fitness profile
  fitness_level   TEXT CHECK (fitness_level IN ('beginner', 'intermediate', 'advanced')),
  primary_goal    TEXT CHECK (primary_goal IN ('fat_loss', 'muscle_gain', 'maintenance', 'general_fitness')),

  -- Availability (days per week they can train, e.g. [1,3,5] = Mon/Wed/Fri)
  workout_days_per_week  INTEGER CHECK (workout_days_per_week BETWEEN 1 AND 7),

  -- Equipment
  equipment_access TEXT[] DEFAULT '{}',   -- e.g. ['barbell', 'dumbbells', 'pull_up_bar']

  -- Nutrition targets (computed by backend, stored here for quick access)
  daily_calorie_target  INTEGER,
  daily_protein_target_g INTEGER,

  -- Dietary preferences
  dietary_preferences TEXT[] DEFAULT '{}', -- e.g. ['vegetarian', 'gluten_free']

  -- Timestamps
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Auto-update updated_at on every change
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER user_profiles_updated_at
  BEFORE UPDATE ON public.user_profiles
  FOR EACH ROW
  EXECUTE FUNCTION public.update_updated_at_column();

-- ── Exercise Library ───────────────────────────────────────────────────────────
-- Seeded exercises available to all users. Admin-managed.
-- Users cannot add to this table (enforced via RLS in migration 002).

CREATE TABLE IF NOT EXISTS public.exercises (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name            TEXT NOT NULL UNIQUE,
  slug            TEXT NOT NULL UNIQUE,       -- URL-safe identifier, e.g. "barbell-bench-press"
  description     TEXT,
  muscle_groups   TEXT[] NOT NULL DEFAULT '{}',  -- e.g. ['chest', 'triceps', 'shoulders']
  equipment       TEXT[] NOT NULL DEFAULT '{}',  -- e.g. ['barbell', 'bench']
  movement_type   TEXT CHECK (movement_type IN ('compound', 'isolation', 'cardio', 'bodyweight')),
  difficulty      TEXT CHECK (difficulty IN ('beginner', 'intermediate', 'advanced')),
  instructions    TEXT[],                    -- Step-by-step instructions
  video_url       TEXT,
  image_url       TEXT,
  is_active       BOOLEAN NOT NULL DEFAULT TRUE,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ── Workout Plans ─────────────────────────────────────────────────────────────
-- A plan is a named template (e.g. "Push Pull Legs", "5x5 Strength").
-- A plan belongs to one user. AI can generate plans; users can edit them.

CREATE TABLE IF NOT EXISTS public.workout_plans (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id         UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  name            TEXT NOT NULL,
  description     TEXT,
  goal            TEXT CHECK (goal IN ('fat_loss', 'muscle_gain', 'maintenance', 'general_fitness')),
  days_per_week   INTEGER CHECK (days_per_week BETWEEN 1 AND 7),
  is_active       BOOLEAN NOT NULL DEFAULT FALSE,  -- only one plan active at a time
  is_ai_generated BOOLEAN NOT NULL DEFAULT FALSE,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TRIGGER workout_plans_updated_at
  BEFORE UPDATE ON public.workout_plans
  FOR EACH ROW
  EXECUTE FUNCTION public.update_updated_at_column();

-- ── Workout Plan Days ─────────────────────────────────────────────────────────
-- Each row is one training day within a plan (e.g. Day 1 = "Chest & Triceps").

CREATE TABLE IF NOT EXISTS public.workout_plan_days (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  plan_id         UUID NOT NULL REFERENCES public.workout_plans(id) ON DELETE CASCADE,
  user_id         UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  day_number      INTEGER NOT NULL CHECK (day_number BETWEEN 1 AND 7),
  name            TEXT NOT NULL,             -- e.g. "Push Day", "Leg Day"
  notes           TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (plan_id, day_number)
);

-- ── Planned Exercises (Plan Day → Exercise mapping) ───────────────────────────

CREATE TABLE IF NOT EXISTS public.plan_day_exercises (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  plan_day_id     UUID NOT NULL REFERENCES public.workout_plan_days(id) ON DELETE CASCADE,
  user_id         UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  exercise_id     UUID NOT NULL REFERENCES public.exercises(id),
  display_order   INTEGER NOT NULL DEFAULT 0,
  target_sets     INTEGER NOT NULL DEFAULT 3,
  target_reps_min INTEGER NOT NULL DEFAULT 8,
  target_reps_max INTEGER NOT NULL DEFAULT 12,
  target_weight_kg NUMERIC(6, 2),           -- NULL = bodyweight or user decides
  rest_seconds    INTEGER NOT NULL DEFAULT 90,
  notes           TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ── Workout Sessions ──────────────────────────────────────────────────────────
-- A session is one actual gym visit. Linked optionally to a plan day.

CREATE TABLE IF NOT EXISTS public.workout_sessions (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id         UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  plan_day_id     UUID REFERENCES public.workout_plan_days(id),  -- NULL = freestyle session
  name            TEXT NOT NULL,
  notes           TEXT,
  started_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  finished_at     TIMESTAMPTZ,               -- NULL = session in progress
  duration_seconds INTEGER,                  -- computed on finish
  status          TEXT NOT NULL DEFAULT 'in_progress'
                  CHECK (status IN ('in_progress', 'completed', 'abandoned')),
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TRIGGER workout_sessions_updated_at
  BEFORE UPDATE ON public.workout_sessions
  FOR EACH ROW
  EXECUTE FUNCTION public.update_updated_at_column();

-- ── Workout Sets ──────────────────────────────────────────────────────────────
-- Each row is one actual set performed during a session.
-- This is the most granular data we capture — foundation for AI recommendations.

CREATE TABLE IF NOT EXISTS public.workout_sets (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id      UUID NOT NULL REFERENCES public.workout_sessions(id) ON DELETE CASCADE,
  user_id         UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  exercise_id     UUID NOT NULL REFERENCES public.exercises(id),
  set_number      INTEGER NOT NULL,
  reps_completed  INTEGER,
  weight_kg       NUMERIC(6, 2),             -- NULL = bodyweight
  rpe             NUMERIC(3, 1)              -- Rate of Perceived Exertion (1-10)
                  CHECK (rpe BETWEEN 1 AND 10),
  duration_seconds INTEGER,                  -- for timed exercises (planks, etc.)
  notes           TEXT,
  is_warmup       BOOLEAN NOT NULL DEFAULT FALSE,
  is_skipped      BOOLEAN NOT NULL DEFAULT FALSE,
  completed_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Index for fast user history queries (AI recommendations need this)
CREATE INDEX IF NOT EXISTS idx_workout_sets_user_exercise
  ON public.workout_sets (user_id, exercise_id, completed_at DESC);

CREATE INDEX IF NOT EXISTS idx_workout_sets_session
  ON public.workout_sets (session_id);

-- ── Food Items ────────────────────────────────────────────────────────────────
-- Shared food database (admin-seeded + user-contributed).
-- Includes Indian/Kerala foods.

CREATE TABLE IF NOT EXISTS public.food_items (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name            TEXT NOT NULL,
  name_local      TEXT,                      -- local language name, e.g. Malayalam
  brand           TEXT,                      -- NULL for generic/whole foods
  barcode         TEXT UNIQUE,
  serving_size_g  NUMERIC(7, 2) NOT NULL DEFAULT 100,
  -- Per serving nutritional data
  calories        NUMERIC(7, 2) NOT NULL,
  protein_g       NUMERIC(6, 2) NOT NULL DEFAULT 0,
  carbs_g         NUMERIC(6, 2) NOT NULL DEFAULT 0,
  fat_g           NUMERIC(6, 2) NOT NULL DEFAULT 0,
  fiber_g         NUMERIC(6, 2) DEFAULT 0,
  sugar_g         NUMERIC(6, 2) DEFAULT 0,
  sodium_mg       NUMERIC(7, 2) DEFAULT 0,
  -- Source
  is_verified     BOOLEAN NOT NULL DEFAULT FALSE,  -- admin-verified nutritional data
  is_ai_estimated BOOLEAN NOT NULL DEFAULT FALSE,  -- AI-generated estimate
  created_by      UUID REFERENCES auth.users(id),  -- NULL = system/admin
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_food_items_name
  ON public.food_items USING gin(to_tsvector('english', name));

-- ── Daily Nutrition Logs ──────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.nutrition_logs (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id         UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  food_item_id    UUID REFERENCES public.food_items(id),
  logged_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  meal_type       TEXT NOT NULL
                  CHECK (meal_type IN ('breakfast', 'lunch', 'dinner', 'snack')),
  quantity_g      NUMERIC(7, 2) NOT NULL,
  -- Denormalised totals (computed at log time for performance)
  calories        NUMERIC(7, 2) NOT NULL,
  protein_g       NUMERIC(6, 2) NOT NULL DEFAULT 0,
  carbs_g         NUMERIC(6, 2) NOT NULL DEFAULT 0,
  fat_g           NUMERIC(6, 2) NOT NULL DEFAULT 0,
  -- AI estimation tracking
  is_ai_estimated BOOLEAN NOT NULL DEFAULT FALSE,
  ai_confidence   TEXT CHECK (ai_confidence IN ('high', 'medium', 'low')),
  user_corrected  BOOLEAN NOT NULL DEFAULT FALSE,
  notes           TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_nutrition_logs_user_date
  ON public.nutrition_logs (user_id, logged_at DESC);

-- ── Body Metrics ──────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.body_metrics (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id         UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  recorded_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  weight_kg       NUMERIC(5, 2),
  body_fat_pct    NUMERIC(4, 1),
  -- Measurements in cm
  chest_cm        NUMERIC(5, 1),
  waist_cm        NUMERIC(5, 1),
  hips_cm         NUMERIC(5, 1),
  left_arm_cm     NUMERIC(5, 1),
  right_arm_cm    NUMERIC(5, 1),
  left_thigh_cm   NUMERIC(5, 1),
  right_thigh_cm  NUMERIC(5, 1),
  notes           TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_body_metrics_user_date
  ON public.body_metrics (user_id, recorded_at DESC);
